import{_ as e,o as i,c as s,a5 as t}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Empaquetado, firmas y registros de plugins","description":"","frontmatter":{"title":"Empaquetado, firmas y registros de plugins","docId":"developer.plugins.packaging-registry","translationKey":"developer.plugins.packaging-registry","locale":"es","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b5c1b8dc63aafc5216467a00317c6670ac6744235abfc724fe372f3a28427ee8","translationRevision":"d6f63b3f63426ff4e129e0a0e9d1663e9559a5e6f2300b2364c81375cf3a1a6f","order":280},"headers":[],"relativePath":"es/developer/plugins/packaging-registry.md","filePath":"es/developer/plugins/packaging-registry.md","lastUpdated":1794611623000}'),r={name:"es/developer/plugins/packaging-registry.md"};function n(o,a,l,p,d,c){return i(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="plugin-packaging-signing-and-registries" tabindex="-1">Empaquetado, firmas y registros de plugins <a class="header-anchor" href="#plugin-packaging-signing-and-registries" aria-label="Permalink to &quot;Empaquetado, firmas y registros de plugins {#plugin-packaging-signing-and-registries}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Distribuye un paquete cuyos bytes, autoridad del editor y compatibilidad se comprueben por separado. Parte de un plugin validado y un destino admitido. Firmar requiere claves privadas fuera del repositorio; delegar desde la raíz del registro es responsabilidad distinta del operador.</p><h2 id="prepare-a-reviewable-archive" tabindex="-1">Preparar un archivo revisable <a class="header-anchor" href="#prepare-a-reviewable-archive" aria-label="Permalink to &quot;Preparar un archivo revisable {#prepare-a-reviewable-archive}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publish</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publisher</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys</span></span></code></pre></div><p><code>build</code> compila el paquete y crea archivos <code>.plugin</code>. Incluye entrada, recursos, idiomas, interfaz y dependencias pertinentes junto a <code>checksums.json</code>. Nativo/proceso necesitan artefactos compatibles; JavaScript permanece portable hasta que addons o funciones de plataforma lo restrinjan.</p><p>Para un archivo ya construido, usa rutas exactas en lugar de comodines sin revisar:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.key.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span></span></code></pre></div><p>Sustituye el nombre por la salida real, incluida su plataforma si corresponde. La firma cubre las sumas, que cubren los archivos. Las claves públicas pueden compartirse; las privadas no deben llegar al código ni a registros.</p><h2 id="trust-and-update-policy" tabindex="-1">Confianza y política de actualización <a class="header-anchor" href="#trust-and-update-policy" aria-label="Permalink to &quot;Confianza y política de actualización {#trust-and-update-policy}&quot;">​</a></h2><p>El protocolo estático utiliza autoridad firmada por raíz y claves delegadas de índice/editor. Aprobar un espacio de nombres no equivale a verificar integridad; un resumen del catálogo Cloud no reemplaza ninguna cadena. El resolvedor comprueba canal, motor, esquema/protocolo/ABI, runtime y destino. Versiones retiradas, revocadas o incompatibles siguen excluidas aunque coincida su hash.</p><p>La instalación muestra primero una revisión. Actualizar automáticamente exige política permitida, paquete sin fijar, editor firmado compatible y ausencia de autoridad nueva; ampliar permisos requiere revisión. Instalar desde catálogo Cloud es distinto de operar registros estáticos y el producto rechaza URLs remotas arbitrarias.</p><h2 id="expected-result-recovery-and-verification" tabindex="-1">Resultado esperado, recuperación y verificación <a class="header-anchor" href="#expected-result-recovery-and-verification" aria-label="Permalink to &quot;Resultado esperado, recuperación y verificación {#expected-result-recovery-and-verification}&quot;">​</a></h2><p>El instalador verifica bytes antes de aplicar el paquete revisado y conserva estado de reversión/recuperación. La preparación de desarrollo queda fuera de su gestión. Ante fallos de confianza, corrige delegación o metadatos sin adoptar anulaciones de firma como política habitual. Si el inicio queda incierto, detén sustituciones y reconcilia el resultado.</p><p>Usa <code>bun scripts/task.ts rust test -p tiktools-plugin-package --locked</code> y pruebas de registro con muestras locales. El <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-plugin-package/src" target="_blank" rel="noreferrer">verificador</a> y <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-plugin-registry/src/model.rs" target="_blank" rel="noreferrer">modelo de registro</a> poseen los formatos; la infraestructura de publicación necesita aceptación separada.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Interpreta el JSON de verificación, no solo el código de salida. <code>verify</code> puede terminar bien con <code>signature.status</code> igual a <code>unsigned</code> o <code>untrusted</code>. Acepta solo <code>verified</code> con ID de paquete, editor y clave esperados, y comprueba la política de distribución. Una clave local <code>--trust</code> prueba esa firma local, no delegación del registro ni aprobación de namespace. Checksums solos no prueban editor ni confianza del updater. La automatización siguiente debe fallar ante cualquier resultado inesperado.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verification.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;const r = await Bun.file(&quot;verification.json&quot;).json(); if (r.signature?.status !== &quot;verified&quot; || r.id !== &quot;acme.hello&quot; || r.signature.publisher !== &quot;acme&quot; || r.signature.keyId !== &quot;acme-1&quot;) throw new Error(&quot;Package trust did not match policy&quot;);&#39;</span></span></code></pre></div>`,18)])])}const g=e(r,[["render",n]]);export{h as __pageData,g as default};
